import java.util.*;

class Solution {
    public int[] dailyTemperatures(int[] temps) {
        int n = temps.length;
        int[] ans = new int[n];
        int[] st = new int[n];      // array-based stack of day indices
        int top = -1;
        for (int i = 0; i < n; i++) {
            while (top >= 0 && temps[st[top]] < temps[i]) {
                int j = st[top--];
                ans[j] = i - j;     // day i is the first warmer day for day j
            }
            st[++top] = i;
        }
        return ans;
    }
}

