class Solution:
    def dailyTemperatures(self, temps: List[int]) -> List[int]:
        ans = [0] * len(temps); st = []
        for i, t in enumerate(temps):
            while st and temps[st[-1]] < t:
                j = st.pop(); ans[j] = i - j
            st.append(i)
        return ans

