function dailyTemperatures(t) {
  const n = t.length, ans = new Array(n).fill(0);
  for (let i = n - 2; i >= 0; i--) {
    let j = i + 1;
    while (j < n && t[j] <= t[i]) j = ans[j] ? j + ans[j] : n;
    ans[i] = j < n ? j - i : 0;
  }
  return ans;
